 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const {
        payload
    } = event.payload;

    let ciClass = payload.data.elements[0];
    let type = payload.data.elements[1];
    let detail = ciClass + '-' + type;

    return {
        event: 'Click insights card',
        value: {
            'Card': 'Cloud Vs NonCloud',
            'Detail': detail
        }
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    var {
        data
    } = event.payload.payload;
    var {
        appServicesCategories
    } = api.state;
    var tab = 0;

    if (data['Group by'] && appServicesCategories.includes(data['Group by'])) {
        tab = appServicesCategories.indexOf(data['Group by']);
    }
    else if (data['elements'] && data['elements'].length === 1 && appServicesCategories.includes(data['elements'][0])) {
        tab = appServicesCategories.indexOf(data['elements'][0]);
    }
    return {
        route: 'application-services',
        fields: null,
        params: {
            "selectedTabIndex": tab.toString(),
            "ts": Date.now()
        },
        redirect: null,
        passiveNavigation: null,
        title: null,
        multiInstField: null,
        targetRoute: 'current',
        external: null
    };
}

